// step-through for the concept diagrams
function stepper(fig){
  const svg = fig.querySelector('svg'), lays = fig.querySelectorAll('.lay');
  let items = [], n = 0;
  if (svg){ let s = -1; const kids = [...svg.children].filter(e => e.tagName !== 'defs');
    kids.forEach((e, i) => { if (e.tagName === 'rect' && kids[i + 1] && kids[i + 1].tagName === 'rect'){ s++; e.dataset.s = s; }
      else if (e.tagName === 'rect'){ e.dataset.s = s; e.classList.add('dg-node'); }
      else if (e.tagName === 'line' || e.tagName === 'path'){ e.dataset.s = s + 1; }
      else if (e.tagName === 'text'){ const prev = kids[i - 1]; e.dataset.s = prev && prev.tagName === 'rect' ? s : s + 1; } });
    items = kids; n = s + 1; }
  else if (lays.length){ items = [...fig.querySelectorAll('.lay, .lay-arr')]; let s = -1; items.forEach(e => { if (e.classList.contains('lay')){ s++; e.dataset.s = s; } else e.dataset.s = s + 1; }); n = s + 1; }
  if (n < 3) return;
  const bar = hx('div', 'dg-bar'), cap = fig.querySelector('figcaption'); fig.insertBefore(bar, cap);
  let k = -1; const b1 = btn(bar, 'Step through ▸', () => { k = k + 1 >= n ? 0 : k + 1; paint(); }), b0 = btn(bar, 'Show all', () => { k = -1; paint(); });
  const info = hx('span', 'dg-info', bar, `${n} steps · tap a box to focus it`);
  const paint = () => { items.forEach(e => { const s = +e.dataset.s; e.classList.toggle('dg-dim', k >= 0 && s > k); e.classList.toggle('dg-cur', k >= 0 && s === k); });
    b1.textContent = k < 0 ? 'Step through ▸' : k + 1 >= n ? 'Start again ↺' : `Next step (${k + 2} of ${n}) ▸`; info.textContent = k < 0 ? `${n} steps · tap a box to focus it` : `Step ${k + 1} of ${n}`; };
  items.forEach(e => { if (e.dataset.s != null && (e.classList.contains('dg-node') || e.classList.contains('lay'))){ e.style.cursor = 'pointer'; e.addEventListener('click', () => { k = +e.dataset.s; paint(); }); } });
  if (svg) svg.querySelectorAll('text').forEach(t => { const s = t.dataset.s; const prev = t.previousElementSibling; if (prev && prev.classList.contains('dg-node')){ t.style.cursor = 'pointer'; t.addEventListener('click', () => { k = +s; paint(); }); } });
}

// home figure: click to run gradient descent on the drawn bowl
function heroGD(svg){
  svg.style.cursor = 'crosshair'; svg.setAttribute('tabindex', '0'); svg.setAttribute('aria-label', 'Contours of a quadratic loss. Click to start gradient descent from that point.');
  const hint = sv('text', {x: 6, y: 12, 'font-size': 10, fill: 'var(--muted)', 'font-family': 'var(--mono)'}, svg); hint.textContent = 'click to drop a start point';
  const a = -18 * Math.PI / 180, ca = Math.cos(a), sa = Math.sin(a), lay = sv('g', {}, svg); let timer = null;
  const run = (x, y) => { [...svg.querySelectorAll('polyline, circle[r="3"]')].forEach(e => e.remove()); clr(lay); clearTimeout(timer);
    let u = (x - 150) * ca + (y - 80) * sa, v = -(x - 150) * sa + (y - 80) * ca; const pts = [];
    for (let i = 0; i < 14; i++){ pts.push([150 + u * ca - v * sa, 80 + u * sa + v * ca]); u *= 1 - 80 / 256; v *= 1 - 80 / 49; }
    const pl = sv('polyline', {fill: 'none', stroke: 'var(--ink)', 'stroke-width': 1.6, 'stroke-linejoin': 'round'}, lay); let i = 0;
    const tick = () => { i++; pl.setAttribute('points', pts.slice(0, i).map(p => p.join(',')).join(' ')); const p = pts[i - 1]; sv('circle', {cx: p[0], cy: p[1], r: 2.6, fill: 'var(--card)', stroke: 'var(--ink)', 'stroke-width': 1.3}, lay); if (i < pts.length) timer = setTimeout(tick, reduced() ? 0 : 110); };
    tick(); hint.textContent = 'zig-zag: the step is too big for the narrow direction'; };
  svg.addEventListener('click', e => { const p = svgPt(svg, e); run(p.x, p.y); e.preventDefault(); });
  svg.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' '){ e.preventDefault(); run(40, 34); } });
}


