    const grad = w => { let g0 = 0, g1 = 0; for (let i = 0; i < N; i++){ const e = w[0] + w[1] * F[i] - ys[i]; g0 += e; g1 += e * F[i]; } return [2 * g0 / N, 2 * g1 / N]; };
