    const S00 = 1, S01 = F.reduce((a, b) => a + b) / N, S11 = F.reduce((a, b) => a + b * b, 0) / N, Sy0 = ys.reduce((a, b) => a + b) / N, Sy1 = F.reduce((a, f, i) => a + f * ys[i], 0) / N, D = S00 * S11 - S01 * S01;
