  const g = plane(st, {x: [-3, 3], y: [-2.5, 2.5], w: 360, h: 300, ticks: true, label: 'Contour map of a surface with a movable point'});
  let p = [1.1, .7], phi, field;
  if (mode === 'grad'){ phi = sld(c, 'Direction u', -180, 180, 1, 60, () => draw(), v => v + '°'); field = seg(c, 'Gradient field', [['off', 'off'], ['on', 'on']], 'off', () => draw()); }
  const sl = mode === 'part' ? sv('svg', {viewBox: '0 0 360 140', class: 'vz-svg', role: 'img', 'aria-label': 'The two slices through the point, with their tangent lines'}, st) : null; if (sl) sl.style.maxWidth = '540px';
  const h = handle(g, 'var(--flame)', () => p, (x, y) => { p = [cl(x, -2.9, 2.9), cl(y, -2.4, 2.4)]; draw(); }, {text: 'p'});
  const draw = () => { const F = SURF[fsel.v], f = F[1], z = f(p[0], p[1]), gr = ngrad(f, p[0], p[1]); clr(g.main); const L = g.main;
    heat(g, f, {nl: 12, hl: mode === 'surf' ? z : null});
    if (mode === 'part'){ seg2(L, g, -3, p[1], 3, p[1], {stroke: 'var(--accent)', 'stroke-width': 2, 'stroke-dasharray': '6 4'}); seg2(L, g, p[0], -2.5, p[0], 2.5, {stroke: 'var(--ink)', 'stroke-width': 2, 'stroke-dasharray': '6 4'}); }
    if (mode === 'grad'){
      if (field.v === 'on') for (let i = -5; i <= 5; i++) for (let j = -4; j <= 4; j++){ const x = i * .55, y = j * .55, q = ngrad(f, x, y), n = nrm(q); if (n > 1e-6) arrow(L, g, x - .2 * q[0] / n, y - .2 * q[1] / n, x + .2 * q[0] / n, y + .2 * q[1] / n, 'var(--ink)', 1.1); }
      const n = nrm(gr), s = n > 1e-9 ? Math.min(1.4, .6 * n) / n : 0; arrow(L, g, p[0], p[1], p[0] + gr[0] * s, p[1] + gr[1] * s, 'var(--ink)', 2.8, '∇f');
      const a = phi.v * Math.PI / 180, u = [Math.cos(a), Math.sin(a)]; arrow(L, g, p[0], p[1], p[0] + .9 * u[0], p[1] + .9 * u[1], 'var(--flame)', 2.4, 'u'); }
    h.at();
    if (mode === 'surf') rd(out, [['f', SURF[fsel.v][0].split('  ')[1] || SURF[fsel.v][0]], ['f(p)', fx(z, 3)], ['p', `(${fx(p[0])}, ${fx(p[1])})`],
      'The black curve is the level set through p: every point where f has the same height as at p. Colour shows height (orange is below 0). Lines bunched together mean a steep slope.']);
    if (mode === 'part'){ clr(sl); const pan = (ox, lab, fx1, x0, slope, col) => { let lo = Infinity, hi = -Infinity; for (let i = 0; i <= 60; i++){ const v = fx1(-3 + i / 10); lo = Math.min(lo, v); hi = Math.max(hi, v); } const pad = (hi - lo) * .12 + .05;
        const q = plane(null, {svg: sl, ox, oy: 18, w: 170, h: 110, x: [-3, 3], y: [lo - pad, hi + pad], grid: false});
        sv('rect', {x: ox, y: 18, width: 170, height: 110, fill: 'none', stroke: 'var(--line)'}, sl); label(sl, ox + 85, 12, lab, 'var(--muted)', {fs: 10.5, fw: 600});
        curve(sl, q, fx1, -3, 3, {stroke: col}); const y0 = fx1(x0); seg2(sl, q, x0 - 1.1, y0 - 1.1 * slope, x0 + 1.1, y0 + 1.1 * slope, {stroke: 'var(--flame)', 'stroke-width': 2}); dot(sl, q, x0, y0, 4, {fill: 'var(--flame)'}); };
      pan(5, `slice y = ${fx(p[1], 1)}: f along x`, x => f(x, p[1]), p[0], gr[0], 'var(--accent)'); pan(185, `slice x = ${fx(p[0], 1)}: f along y`, y => f(p[0], y), p[1], gr[1], 'var(--ink)');
      rd(out, [['f(p)', fx(z, 3)], ['∂f/∂x (slope of the left slice)', fx(gr[0], 3)], ['∂f/∂y (slope of the right slice)', fx(gr[1], 3)], 'A partial derivative freezes every variable but one and asks for the slope along what is left. The dashed lines on the map are the two slices.']); }
    if (mode === 'grad'){ const a = phi.v * Math.PI / 180, u = [Math.cos(a), Math.sin(a)], D = dt2(gr, u), n = nrm(gr);
      rd(out, [['∇f(p)', `(${fx(gr[0])}, ${fx(gr[1])})`], ['‖∇f‖', fx(n)], ['Slope in direction u: ∇f · u', fx(D)], ['Steepest possible slope', fx(n)],
        Math.abs(D - n) < .02 * (n + .01) ? 'u points along ∇f: this is the steepest way up.' : Math.abs(D + n) < .02 * (n + .01) ? 'u points against ∇f: steepest way down. Gradient descent steps this way.' : Math.abs(D) < .02 * (n + .01) ? 'u is along the contour line: the height does not change at first.' : 'Turn u. The slope ∇f · u is largest along ∇f and zero along the contour line. ∇f always crosses contour lines at a right angle.']); } };
  live(host, draw);
