  let seed = 5; btn(c, 'New sample', () => { seed++; draw(); });
  const g = plane(st, {x: [-4, 4], y: [-3.33, 3.33], w: 360, h: 300, label: 'Samples from a two-dimensional Gaussian'});
  const s2 = mode === 'lin' ? sv('svg', {viewBox: '0 0 360 150', class: 'vz-svg', role: 'img', 'aria-label': 'Histogram of the projection w dot X'}, st) : null; if (s2) s2.style.maxWidth = '540px';
