  let hs = []; const rebuild = () => { clr(g.top); hs = P.map((_, i) => handle(g, 'var(--ink)', () => P[i], (x, y) => { P[i] = [cl(x, -2.9, 2.9), cl(y, -2.4, 2.4)]; draw(); }, {r: 5.5, label: 'point ' + (i + 1)})); draw(); };
  const draw = () => { clr(g.main); const L = g.main, n = P.length, mx = P.reduce((s, p) => s + p[0], 0) / n, my = P.reduce((s, p) => s + p[1], 0) / n; let sxy = 0, sxx = 0, syy = 0;
    P.forEach(p => { const dx = p[0] - mx, dy = p[1] - my; sxy += dx * dy; sxx += dx * dx; syy += dy * dy; const pos = dx * dy >= 0;
      sv('rect', {x: Math.min(g.X(mx), g.X(p[0])), y: Math.min(g.Y(my), g.Y(p[1])), width: Math.abs(g.X(p[0]) - g.X(mx)), height: Math.abs(g.Y(p[1]) - g.Y(my)), fill: pos ? 'var(--accent)' : 'var(--flame)', 'fill-opacity': .14, stroke: pos ? 'var(--accent)' : 'var(--flame)', 'stroke-opacity': .4}, L); });
    seg2(L, g, mx, -3, mx, 3, {stroke: 'var(--ink)', 'stroke-dasharray': '5 4'}); seg2(L, g, -4, my, 4, my, {stroke: 'var(--ink)', 'stroke-dasharray': '5 4'}); hs.forEach(h => h.at());
    const cov = sxy / (n - 1), rr = sxy / Math.sqrt(sxx * syy || 1);
    rd(out, [['Covariance', fx(cov, 3)], ['Correlation r', fx(rr, 3)], ['Points', String(n)],
      'Each rectangle runs from the mean point (dashed cross) to a data point. Green ones (both above or both below the mean) push the covariance up; orange ones pull it down. Covariance is their average signed area. "Stretch y" doubles the covariance but leaves r unchanged: r has no units.']); };
  rebuild();
